function fieldHtml(f,v){const id=esc(f.id),label=esc(f.label),unit=esc(f.unit||''),vw=f.visibleWhen||null,cond=vw?` data-visible-when-field="${esc(vw.field||'')}" data-visible-when-value="${esc(vw.equals??'')}"`:'';const tip=f.help?`<span class="loom-inline-tip" tabindex="0" data-loom-tip="${esc(f.help)}">?</span>`:'';let input='';if(f.type==='range')input=`<input data-field="${id}" type="range" min="${esc(f.min)}" max="${esc(f.max)}" step="${esc(f.step||1)}" value="${esc(v)}"><div class="msg" data-value="${id}">${esc(v)}${unit}</div>`;else if(f.type==='color')input=`<input data-field="${id}" type="color" value="${esc(v||'#000000')}">`;else if(f.type==='select')input=`<select data-field="${id}">${(f.options||[]).map(o=>{const val=typeof o==='string'?o:o.value,lab=typeof o==='string'?o:o.label;return `<option value="${esc(val)}" ${String(val)===String(v)?'selected':''}>${esc(lab)}</option>`}).join('')}</select>`;else if(f.type==='checkbox')input=`<label class="field-check"><input data-field="${id}" type="checkbox" ${v!==false?'checked':''}><span>${label}</span></label>`;else if(f.type==='textarea')input=`<textarea data-field="${id}" rows="${esc(f.rows||4)}" placeholder="${esc(f.placeholder||'')}">${esc(v??'')}</textarea>`;else input=`<input data-field="${id}" type="${f.type==='number'?'number':'text'}" value="${esc(v??'')}">`;const help=f.help?`<div class="field-help">${esc(f.help)}</div>`:'';return f.type==='checkbox'?`<div class="field"${cond}>${input}${tip}${help}</div>`:`<div class="field"${cond}><label><span>${label}${tip}</span>${unit?`<span>${unit}</span>`:''}</label>${input}${help}</div>`}
function syncConditionalFields(scope){scope.querySelectorAll('[data-visible-when-field]').forEach(row=>{const card=row.closest('.module')||scope,field=row.dataset.visibleWhenField,want=row.dataset.visibleWhenValue,src=card.querySelector(`[data-field="${CSS.escape(field)}"]`);let actual='';if(src)actual=src.type==='checkbox'?(src.checked?'true':'false'):String(src.value);row.classList.toggle('hidden',actual!==String(want))})}
function bindConditionalFields(scope){syncConditionalFields(scope);scope.querySelectorAll('[data-field]').forEach(el=>{el.addEventListener('input',()=>syncConditionalFields(el.closest('.module')||scope));el.addEventListener('change',()=>syncConditionalFields(el.closest('.module')||scope))})}
const ADMIN_UI_KEY='loom:admin-settings-ui:v1';
function adminUiRead(){try{return {open:{},recent:{},...JSON.parse(localStorage.getItem(ADMIN_UI_KEY)||'{}')}}catch{return {open:{},recent:{}}}}
function adminUiWrite(v){try{localStorage.setItem(ADMIN_UI_KEY,JSON.stringify(v))}catch{}}
function adminSectionKey(scope,key){return `${scope}:${key}`}
function sortAdminCards(container,scope){if(!container)return;const ui=adminUiRead(),cards=[...container.children].filter(x=>x.matches?.('[data-admin-config-card]'));cards.sort((a,b)=>(ui.recent[adminSectionKey(scope,b.dataset.adminConfigCard)]||0)-(ui.recent[adminSectionKey(scope,a.dataset.adminConfigCard)]||0));for(const card of cards)container.appendChild(card)}
function touchAdminCard(card,scope){if(!card)return;const ui=adminUiRead(),key=adminSectionKey(scope,card.dataset.adminConfigCard||card.dataset.adminStaticSection||'section');ui.recent[key]=Date.now();adminUiWrite(ui);if(card.parentElement?.matches?.('.grid'))sortAdminCards(card.parentElement,scope)}
function decorateAdminCard(card,scope,key,title){if(!card)return;const stateKey=adminSectionKey(scope,key),ui=adminUiRead();card.dataset.adminConfigCard=key;card.classList.add('admin-config-card');if(!card.querySelector(':scope > .admin-settings-body')){const nodes=[...card.childNodes],body=document.createElement('div');body.className='admin-settings-body';nodes.forEach(n=>body.appendChild(n));const toggle=document.createElement('button');toggle.type='button';toggle.className='admin-settings-toggle';toggle.innerHTML=`<span class="admin-settings-title">${esc(title||key)}</span><span class="admin-settings-chevron">⌄</span>`;card.append(toggle,body);toggle.addEventListener('click',()=>{const next=!card.classList.contains('is-open');card.classList.toggle('is-open',next);toggle.setAttribute('aria-expanded',next?'true':'false');const fresh=adminUiRead();fresh.open[stateKey]=next;adminUiWrite(fresh)});body.addEventListener('input',()=>touchAdminCard(card,scope));body.addEventListener('change',()=>touchAdminCard(card,scope));body.addEventListener('click',e=>{if(e.target.closest('button,a'))touchAdminCard(card,scope)})}const open=ui.open[stateKey]===true;card.classList.toggle('is-open',open);card.querySelector(':scope > .admin-settings-toggle')?.setAttribute('aria-expanded',open?'true':'false')}
function decorateRenderedCards(container,scope){container?.querySelectorAll(':scope > [data-admin-config-card]').forEach(card=>decorateAdminCard(card,scope,card.dataset.adminConfigCard,card.dataset.adminTitle));sortAdminCards(container,scope)}
function decorateProjectStaticCards(){document.querySelectorAll('#projectSettingsPanel [data-admin-static-section]').forEach(card=>decorateAdminCard(card,'project-static',card.dataset.adminStaticSection,card.dataset.adminTitle))}
function socialCanonicalPreview(platform,raw){let value=String(raw||'').trim();if(!value)return 'Enter a username / handle — LOOM builds the URL locally.';const hosts={youtube:['youtube.com','www.youtube.com','youtu.be'],facebook:['facebook.com','www.facebook.com','fb.com','www.fb.com'],tiktok:['tiktok.com','www.tiktok.com'],instagram:['instagram.com','www.instagram.com']};if(/^https?:\/\//i.test(value)){try{const u=new URL(value),h=u.hostname.toLowerCase();if(!(hosts[platform]||[]).includes(h))return `⚠ That URL does not look like ${platform}. Nothing is fetched or retried.`;return `✓ ${u.href}`}catch{return '⚠ That URL is malformed. Nothing is fetched or retried.'}}value=value.replace(/^@/,'').replace(/^\/+|\/+$/g,'').trim();if(!value)return 'Enter a username / handle.';if(platform==='youtube'){if(/^UC[A-Za-z0-9_-]{10,}$/.test(value))return `✓ https://www.youtube.com/channel/${value}`;return `✓ https://www.youtube.com/@${value}`}if(platform==='tiktok')return `✓ https://www.tiktok.com/@${value}`;if(platform==='instagram')return `✓ https://www.instagram.com/${value}/`;if(platform==='facebook')return `✓ https://www.facebook.com/${value}`;return value}
function bindSocialLinkHelpers(scope){const card=scope.querySelector?.('[data-module="loom.social-links"]');if(!card)return;const map={youtubeUrl:'youtube',facebookUrl:'facebook',tiktokUrl:'tiktok',instagramUrl:'instagram'};for(const [field,platform] of Object.entries(map)){const el=card.querySelector(`[data-field="${field}"]`);if(!el)continue;let preview=el.parentElement.querySelector('.social-normalize-preview');if(!preview){preview=document.createElement('div');preview.className='social-normalize-preview';el.insertAdjacentElement('afterend',preview)}const draw=()=>preview.textContent=socialCanonicalPreview(platform,el.value);el.addEventListener('input',draw);draw()}}
const ORB_EMOJIS=['🗒️','📝','📋','📌','📍','📎','📁','📂','🗂️','🧾','📦','🛒','🧺','🥬','🍏','🥕','🍽️','🥗','🧑‍🍳','⭐','❤️','💚','💡','🔔','⏰','📅','🗓️','✅','☑️','❌','⚙️','🛠️','🔧','🔨','🧰','🔍','🔎','📊','📈','📉','💬','✉️','📨','📢','🔐','🔑','👤','👥','🏠','🌱','🌿','🌎','☀️','🌙','✨','⚡','🔥','💧','🎯','🏆','🎨','🧩','🎵','🎬','📷','💻','📱','🖥️','⌨️','🖱️','🔗','🌐','🚀','🛰️','🧭','🗺️','🚗','✈️','💰','💳','🏷️','🎁','📚','📖','✏️','🖊️','🔖','🧠','💭','🧪','🔬','🩺','🏃','💪','🧘','🎮','🎲','♻️','🟢','🔵','🟣','🟡','🟠','🔴','⚫','⚪'];
function orbFallback(name){const w=String(name||'').trim().split(/\s+/).filter(Boolean);return (w.length>=2?(w[0][0]+w[1][0]):((w[0]||'MD').slice(0,2))).toUpperCase()}
function orbManagerHtml(tool,m){const saved=m.values?.orbTargets||{};const targets=(state?.modules||[]).filter(x=>x.actionId!==m.actionId&&x.presentation?.role==='content');return `<div class="admin-tool" data-orb-manager><b>${esc(tool.label||'Orb Modules')}</b><div class="msg">Capture content modules into the footer Orb Dock. Emoji is optional; when blank, LOOM generates a two-letter badge automatically. Any Unicode emoji may be pasted.</div><div class="orb-admin-list">${targets.map(t=>{const meta=t.presentation?.orb||{},cfg=saved[t.actionId]||{},required=!!meta.required,captured=required?true:(cfg.captured??meta.defaultCaptured??false),emoji=cfg.emoji??meta.defaultEmoji??'';return `<div class="orb-admin-row" data-orb-target="${esc(t.actionId)}"><input type="checkbox" data-orb-captured ${captured?'checked':''} ${required?'disabled':''}><div><strong>${esc(t.name)}</strong><small>${esc(t.actionId)} · fallback ${esc(orbFallback(meta.label||t.name))}${required?' · required orb':''}</small></div><input type="text" maxlength="8" data-orb-emoji value="${esc(emoji)}" placeholder="${esc(orbFallback(meta.label||t.name))}"><button type="button" class="reset" data-emoji-toggle>😀</button><div class="emoji-pop" style="grid-column:1/-1">${ORB_EMOJIS.map(e=>`<button type="button" data-emoji-value="${e}">${e}</button>`).join('')}</div></div>`}).join('')||'<div class="empty">No content modules are currently eligible.</div>'}</div><div class="buttons"><button class="save" type="button" data-orb-save>Save Orb Modules</button></div></div>`}
function readAdminField(el,f){if(f.type==='checkbox')return !!el.checked;if(f.type==='range'||f.type==='number')return Number(el.value);return el.value}
function showcaseManagerHtml(tool,m){
  const p=state?.project_profile||{},mode=m.values?.bioMode==='custom'?'custom':'project',projectBio=String(p.bio||''),customBio=String(m.values?.bioOverride||''),shownBio=mode==='custom'?customBio:projectBio,has=!!m.values?.hasImage,ver=encodeURIComponent(String(m.values?.imageVersion||Date.now())),project=encodeURIComponent($('#project')?.value||state?.project||''),img=has?`../api/project-asset.php?project=${project}&path=${encodeURIComponent(m.values?.imageAsset||'assets/showcase.png')}&v=${ver}`:'';
  return `<div class="admin-tool showcase-admin" data-showcase-manager><div><b>${esc(tool.label||'Showcase Content')}</b><div class="msg">The image preserves transparency and centers without cropping by default. Use the module controls above for transparent, project, LOOM, white, or custom media backgrounds. The summary follows the exact project bio by default.</div></div><div class="showcase-admin-grid"><div><div class="showcase-admin-drop" data-showcase-drop>${img?`<img src="${esc(img)}" alt="Showcase preview">`:`<div><b>Drop showcase image here</b><div class="msg">or choose any browser-readable image below</div></div>`}</div><input style="margin-top:8px" data-showcase-file type="file" accept="image/*"><div class="buttons"><button class="secondary" type="button" data-showcase-upload>${has?'Replace Image':'Upload Image'}</button>${has?'<button class="reset" type="button" data-showcase-remove>Remove Image</button>':''}</div></div><div class="showcase-admin-copy"><div style="display:flex;justify-content:space-between;gap:8px;align-items:center"><b>Summary / bio</b><span class="showcase-mode ${mode==='custom'?'custom':''}">${mode==='custom'?'Custom Showcase Bio':'Following Project Bio'}</span></div><textarea data-showcase-bio maxlength="1800">${esc(shownBio)}</textarea><div class="msg">Current canonical project bio: ${projectBio?esc(projectBio):'<i>blank</i>'}</div><div class="buttons"><button class="save" type="button" data-showcase-save>Save as Custom Bio</button><button class="reset" type="button" data-showcase-project>Use Project Bio</button></div></div></div><div class="msg" data-showcase-msg></div></div>`
}
async function showcaseUpload(card,file){
  if(!file)return;const msg=card.querySelector('[data-showcase-msg]');if(msg)msg.textContent='Preparing image…';
  try{const png=await imageFileToProjectPngDataUrl(file);state=await post({action:'showcase-image-upload',project:$('#project').value,pngBase64:png});renderProjectProfile();renderModules()}catch(e){if(msg)msg.textContent=e.message}
}
function bindShowcaseManagers(scope){
  scope.querySelectorAll('[data-showcase-manager]').forEach(card=>{
    const input=card.querySelector('[data-showcase-file]'),drop=card.querySelector('[data-showcase-drop]');
    card.querySelector('[data-showcase-upload]')?.addEventListener('click',()=>{const f=input?.files?.[0];if(f)showcaseUpload(card,f);else input?.click()});
    input?.addEventListener('change',()=>{const f=input.files?.[0];if(f)showcaseUpload(card,f)});
    if(drop){['dragenter','dragover'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.add('drag')}));['dragleave','drop'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.remove('drag')}));drop.addEventListener('drop',e=>{const f=[...(e.dataTransfer?.files||[])].find(x=>String(x.type||'').startsWith('image/'));if(f)showcaseUpload(card,f)})}
    card.querySelector('[data-showcase-save]')?.addEventListener('click',async()=>{const msg=card.querySelector('[data-showcase-msg]');try{state=await post({action:'showcase-bio-save',project:$('#project').value,bioMode:'custom',bioOverride:card.querySelector('[data-showcase-bio]')?.value||''});renderModules();toastOk('Custom Showcase bio applied.')}catch(e){if(msg)msg.textContent=e.message}});
    card.querySelector('[data-showcase-project]')?.addEventListener('click',async()=>{const msg=card.querySelector('[data-showcase-msg]');try{state=await post({action:'showcase-bio-save',project:$('#project').value,bioMode:'project'});renderProjectProfile();renderModules();toastOk('Showcase is following the Project Bio again.')}catch(e){if(msg)msg.textContent=e.message}});
    card.querySelector('[data-showcase-remove]')?.addEventListener('click',async()=>{const msg=card.querySelector('[data-showcase-msg]');try{state=await post({action:'showcase-image-remove',project:$('#project').value});renderModules()}catch(e){if(msg)msg.textContent=e.message}})
  })
}
function toolHtml(tool,m){
  if(tool.type==='favicon'){const mode=m.values?.faviconMode||'logo';return `<div class="admin-tool"><b>${esc(tool.label||'Favicon')}</b><div class="msg">Current source: ${mode==='custom'?'Custom favicon.ico':'Current project logo'}</div><input type="file" accept="image/*" data-favicon-file><div class="buttons"><button class="secondary" data-favicon-upload>Upload image → favicon.ico</button><button class="reset" data-favicon-logo>Use Current Logo</button></div></div>`}
  if(tool.type==='orb-manager')return orbManagerHtml(tool,m);
  if(tool.type==='html-framer-manager')return `<div class="admin-tool"><b>${esc(tool.label||'HTML Frames')}</b><div class="msg">ZIP → isolated LOOM frame module. Packages are stored in the Instance Vault.</div><div data-html-framer-manager><div class="html-framer-empty">Loading HTML frames…</div></div></div>`;
  if(tool.type==='showcase-manager')return showcaseManagerHtml(tool,m);
  if(tool.type==='config-presets'){
    const available=(tool.presets||[]).filter(p=>!p.requiresExtension||state?.extensions?.[p.requiresExtension]);
    const providerNames=[...new Set(available.map(p=>p.requiresExtension&&state?.extensions?.[p.requiresExtension]?.label).filter(Boolean))];
    return `<div class="admin-tool"><b>${esc(tool.label||'Presets')}</b>${providerNames.length?`<div class="msg">Project provider: ${providerNames.map(esc).join(', ')}</div>`:''}<div class="buttons">${available.map(p=>`<button class="${p.id.includes('project')?'secondary':'reset'}" data-config-preset="${esc(p.id)}">${esc(p.label||p.id)}</button>`).join('')}</div></div>`
  }
  return ''
}
async function imageFileToPngDataUrl(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{const c=document.createElement('canvas');c.width=c.height=64;const x=c.getContext('2d'),scale=Math.min(64/img.naturalWidth,64/img.naturalHeight),w=img.naturalWidth*scale,h=img.naturalHeight*scale;x.clearRect(0,0,64,64);x.drawImage(img,(64-w)/2,(64-h)/2,w,h);URL.revokeObjectURL(url);resolve(c.toDataURL('image/png'))};img.onerror=()=>reject(new Error('Browser could not decode image'));img.src=url})}
async function imageFileToProjectPngDataUrl(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{const max=1600,scale=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.naturalWidth*scale));c.height=Math.max(1,Math.round(img.naturalHeight*scale));const x=c.getContext('2d');x.clearRect(0,0,c.width,c.height);x.drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(url);resolve(c.toDataURL('image/png'))};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Browser could not decode image'))};img.src=url})}
function domainLandingToolHtml(tool,m){
  const d=globalState?.domainRouting||{},saved=d.saved||{},effective=d.effective||{},projects=d.availableProjects||[];
  const mode=saved.mode==='project'?'project':'loom-home',selected=String(saved.project||'');
  const baseUrl=new URL('../',location.href).href,homeUrl=new URL('../home/',location.href).href;
  const options=projects.map(p=>`<option value="${esc(p.slug)}" ${p.slug===selected?'selected':''}>${esc(p.name||p.slug)} · ${esc(p.source||'project')}</option>`).join('');
  const status=effective.mode==='project'&&effective.project
    ? `Active now: <b>${esc(projects.find(p=>p.slug===effective.project)?.name||effective.project)}</b> owns the installation base URL.`
    : effective.reason==='module-disabled'
      ? 'Domain Landing is disabled in Module Control, so the installation base currently opens LOOM Home. The saved preference is preserved.'
