  return `<div class="admin-tool" data-domain-landing><b>${esc(tool.label||'Base URL Routing')}</b><div class="field"><label>Base URL opens</label><select data-domain-mode><option value="loom-home" ${mode==='loom-home'?'selected':''}>LOOM Home</option><option value="project" ${mode==='project'?'selected':''}>A LOOM project</option></select></div><div class="field" data-domain-project-wrap ${mode==='project'?'':'hidden'}><label>Landing project</label><select data-domain-project><option value="">Choose project…</option>${options}</select><div class="field-help">Release projects and Instance Projects are both supported. Archived/missing projects automatically fall back to LOOM Home.</div></div><div class="domain-landing-status ${effective.reason?'warn':''}" data-domain-status>${status}</div><div class="domain-landing-grid"><div class="domain-landing-url"><b>Installation base</b><code>${esc(baseUrl)}</code></div><div class="domain-landing-url"><b>Permanent LOOM Home</b><code>${esc(homeUrl)}</code></div></div><div class="buttons"><button class="save" data-domain-save>Save Base Landing</button><button class="reset" data-domain-home>Restore LOOM Home to Base</button><a class="nav" style="text-decoration:none" href="${esc(baseUrl)}" target="_blank">Open Base URL</a><a class="nav" style="text-decoration:none" href="${esc(homeUrl)}" target="_blank">Open LOOM Home</a></div><div class="msg" data-domain-msg></div></div>`
}
function globalToolHtml(tool,m){if(tool.type==='domain-landing-manager')return domainLandingToolHtml(tool,m);if(tool.type==='delegated-access-manager')return `<div class="admin-tool"><b>${esc(tool.label||'Delegated Access')}</b><div class="msg">Manage System Owner-safe LOOM Admins and project-scoped delegates from the Access tab.</div><div class="buttons"><button class="secondary" type="button" onclick="showTab('access')">Open Access Manager</button></div></div>`;return ''}
function bindDomainLandingManagers(box){
  box.querySelectorAll('[data-domain-landing]').forEach(host=>{
    const mode=host.querySelector('[data-domain-mode]'),projectWrap=host.querySelector('[data-domain-project-wrap]'),project=host.querySelector('[data-domain-project]'),msg=host.querySelector('[data-domain-msg]');
    const sync=()=>{projectWrap.hidden=mode.value!=='project'};mode.addEventListener('change',sync);sync();
    host.querySelector('[data-domain-save]')?.addEventListener('click',async()=>{
      if(mode.value==='project'&&!project.value){msg.textContent='Choose a landing project first.';return}
      const label=mode.value==='project'?(project.options[project.selectedIndex]?.textContent||project.value):'LOOM Home';
      if(!confirm(`Make the LOOM installation base URL open ${label}?\n\nLOOM Home will remain available at /home/.`))return;
      msg.textContent='Saving routing…';
      try{globalState=await post({action:'domain-landing-save',mode:mode.value,project:project.value});renderGlobalModules();msg.textContent=''}catch(e){msg.textContent=e.message}
    });
    host.querySelector('[data-domain-home]')?.addEventListener('click',async()=>{
      if(!confirm('Restore LOOM Home as the installation base landing page?'))return;
      msg.textContent='Restoring LOOM Home…';
      try{globalState=await post({action:'domain-landing-home'});renderGlobalModules()}catch(e){msg.textContent=e.message}
    });
  })
}
function renderGlobalModules(){const box=$('#globalModules'),mods=globalState?.modules||[];box.innerHTML=mods.map(m=>{const fields=m.admin_settings?.fields||[],title=m.admin_settings?.title||m.name;return `<section class="module" data-module="${esc(m.actionId)}" data-admin-config-card="${esc(m.actionId)}" data-admin-title="${esc(title)}"><div class="eyebrow">GLOBAL · ${esc(m.actionId)}</div><h2>${esc(title)}</h2><div class="desc">${esc(m.admin_settings?.description||m.description)}</div>${fields.map(f=>fieldHtml(f,m.values?.[f.id]??m.defaults?.[f.id])).join('')}${(m.admin_settings?.tools||[]).map(t=>globalToolHtml(t,m)).join('')}${fields.length?`<div class="buttons"><button class="save" data-global-save>Save LOOM Setting</button><button class="reset" data-global-reset>Reset LOOM Default</button></div>`:''}<div class="msg" data-msg></div></section>`}).join('');box.querySelectorAll('input[type=range]').forEach(el=>el.oninput=()=>{const f=mods.flatMap(x=>x.admin_settings?.fields||[]).find(x=>x.id===el.dataset.field),out=box.querySelector(`[data-value="${CSS.escape(el.dataset.field)}"]`);if(out)out.textContent=el.value+(f?.unit||'')});bindConditionalFields(box);bindDomainLandingManagers(box);bindSocialLinkHelpers(box);box.querySelectorAll('[data-global-save]').forEach(btn=>btn.onclick=async()=>{const card=btn.closest('.module'),m=mods.find(x=>x.actionId===card.dataset.module),vals={};for(const f of m.admin_settings.fields){const el=card.querySelector(`[data-field="${CSS.escape(f.id)}"]`);vals[f.id]=readAdminField(el,f)}try{globalState=await post({action:'global-save',moduleId:card.dataset.module,values:vals});renderGlobalModules();window.LoomToast?.configureGlobal?.(globalState);await refreshAdminCube();toastOk(`${m.admin_settings?.title||m.name} settings applied.`)}catch(e){card.querySelector('[data-msg]').textContent=e.message;toastErr(e.message)}});box.querySelectorAll('[data-global-reset]').forEach(btn=>btn.onclick=async()=>{const card=btn.closest('.module');try{globalState=await post({action:'global-reset',moduleId:card.dataset.module});renderGlobalModules();window.LoomToast?.configureGlobal?.(globalState);await refreshAdminCube();toastOk('LOOM defaults restored.','Defaults restored')}catch(e){card.querySelector('[data-msg]').textContent=e.message;toastErr(e.message)}});decorateRenderedCards(box,'loom')}

