async function htmlFramerRequest(action,opts={}){
  const project=$('#project').value;
  if(opts.file){
    const fd=new FormData();fd.append('action',action);fd.append('project',project);fd.append('clientId',identity.clientId);fd.append('zip',opts.file,opts.file.name);
    if(opts.entrypoint)fd.append('entrypoint',opts.entrypoint);if(opts.replaceId)fd.append('replaceId',opts.replaceId);
    const r=await fetch('../api/html-framer.php',{method:'POST',body:fd,cache:'no-store'}),j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'HTML Framer request failed');return j
  }
  if(action==='list'){
    const r=await fetch(`../api/html-framer.php?action=list&project=${encodeURIComponent(project)}&clientId=${encodeURIComponent(identity.clientId)}&_=${Date.now()}`,{cache:'no-store'}),j=await r.json();
    if(!r.ok||!j.ok)throw new Error(j.error||'HTML Framer request failed');return j
  }
  const r=await fetch('../api/html-framer.php',{method:'POST',headers:{'Content-Type':'application/json'},cache:'no-store',body:JSON.stringify({action,project,clientId:identity.clientId,...opts})});
  const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'HTML Framer request failed');return j
}
function htmlFramerAnalysisHtml(a){
  if(!a)return '';
  const size=Math.round((a.totalBytes||0)/1024);
  const repairs=(a.repairs||[]).length,missing=(a.missingRefs||[]).length,warns=[...(a.warnings||[])];
  if(missing)warns.push(`${missing} local reference${missing===1?'':'s'} could not be resolved automatically.`);
  const reader=a.actionReader||{},readerText=`${esc(reader.trackableCount||0)} trackable UI action${Number(reader.trackableCount||0)===1?'':'s'} · ${esc(reader.functionCandidateCount||0)} JS function candidate${Number(reader.functionCandidateCount||0)===1?'':'s'} · ${esc(reader.listenerEventCount||0)} listener registration${Number(reader.listenerEventCount||0)===1?'':'s'}`;
  return `<div class="html-framer-analysis"><b>${esc(a.fileCount||0)} files · ${esc(a.cssCount||0)} CSS · ${esc(a.jsCount||0)} JS · ${esc(size)} KB</b><br><b>Action Reader:</b> ${readerText}. ${(reader.functionCandidateCount||0)?'Function names are discovery hints; LOOM tracks observable user interactions without wrapping arbitrary foreign functions. ':''}${repairs?`${esc(repairs)} safe path repair${repairs===1?'':'s'} detected. `:''}${(a.autoAttachCss||[]).length?`${esc(a.autoAttachCss.length)} CSS root${a.autoAttachCss.length===1?'':'s'} will be auto-attached. `:''}${(a.autoAttachJs||[]).length?`${esc(a.autoAttachJs.length)} JS root${a.autoAttachJs.length===1?'':'s'} will be auto-attached.`:''}${warns.length?`<div class="html-framer-warnings">${warns.slice(0,8).map(x=>esc(x)).join('<br>')}</div>`:''}</div>`
}
function htmlFramerRows(frames){
  if(!frames?.length)return '<div class="html-framer-empty">No HTML frame modules yet. Drop a ZIP above to create one.</div>';
  return `<div class="html-framer-list">${frames.map((f,i)=>`<div class="html-framer-row" data-hf-id="${esc(f.id)}"><div class="html-framer-row-head"><label class="field-check"><input type="checkbox" data-hf-enabled ${f.enabled!==false?'checked':''}><span>Live</span></label><label class="field-check"><input type="checkbox" data-hf-track ${f.actionReaderEnabled!==false?'checked':''}><span>Track actions</span></label><input class="html-framer-row-title" data-hf-title value="${esc(f.title||'HTML Frame')}"><div class="buttons" style="margin:0"><button class="reset" data-hf-move="up" ${i===0?'disabled':''}>↑</button><button class="reset" data-hf-move="down" ${i===frames.length-1?'disabled':''}>↓</button><button class="danger" data-hf-delete>Delete</button></div></div><div class="html-framer-meta"><code>${esc(f.id)}</code> · entry <code>${esc(f.entrypoint||'')}</code> · ${esc(f.fileCount||0)} files · revision ${esc(f.revision||1)}${f.zipName?` · ${esc(f.zipName)}`:''} · Action Reader ${f.actionReaderEnabled===false?'off':`${esc(f.actionReader?.trackableCount||0)} cataloged`}</div><div class="html-framer-controls"><div><label style="font-size:9px;font-weight:900;color:#58705f">Frame height · <span data-hf-height-value>${esc(f.height||520)}px</span></label><input data-hf-height type="range" min="200" max="1600" step="10" value="${esc(f.height||520)}" style="width:100%"></div><button class="save" data-hf-save>Save Frame</button></div>${(f.warnings||[]).length|| (f.missingRefs||[]).length?`<div class="html-framer-warnings">${[...(f.warnings||[]),...((f.missingRefs||[]).slice(0,5).map(x=>`Unresolved: ${x.from} → ${x.raw}`))].slice(0,8).map(x=>esc(x)).join('<br>')}</div>`:''}</div>`).join('')}</div>`
}
async function htmlFramerLoad(node){
  try{const data=await htmlFramerRequest('list');node._hfData=data;htmlFramerRender(node)}catch(e){node.innerHTML=`<div class="html-framer-warnings">${esc(e.message)}</div>`}
}
function htmlFramerRender(node){
  const data=node._hfData||{frames:[]},a=node._hfAnalysis||null,candidates=a?.htmlCandidates||[],needs=!!a?.needsEntrypoint;
  node.innerHTML=`<div class="html-framer-drop" data-hf-drop><b>Drop one HTML package ZIP here</b><div class="msg">LOOM preserves valid links, discovers dependencies and auto-attaches orphan CSS/JS roots.</div><input data-hf-file type="file" accept=".zip,application/zip">${needs?`<div class="field"><label>Multiple HTML files found · choose the entrypoint</label><select data-hf-entry>${candidates.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select></div>`:''}<div class="buttons"><button class="secondary" data-hf-analyze>Analyze ZIP</button><button class="save" data-hf-publish ${!node._hfFile?'disabled':''}>${needs?'Publish Selected Entrypoint':'Publish Frame Module'}</button></div>${htmlFramerAnalysisHtml(a)}</div><div class="admin-tool" style="margin-top:10px"><b>Capture Static URL</b><div class="msg">Enter an http/https page. LOOM downloads a bounded, same-origin static snapshot into the Instance Vault. It is not a live production embed and does not stay synchronized.</div><div class="field"><label>Web page URL</label><input data-hf-url type="url" placeholder="https://example.com/page"></div><div class="buttons"><button class="secondary" data-hf-capture>Capture URL → Static Frame</button></div><div class="msg" data-hf-capture-msg></div></div>${htmlFramerRows(data.frames||[])}`;
  const drop=node.querySelector('[data-hf-drop]'),fileInput=node.querySelector('[data-hf-file]');
  const choose=async file=>{if(!file)return;node._hfFile=file;try{const r=await htmlFramerRequest('analyze',{file});node._hfAnalysis=r.analysis;htmlFramerRender(node)}catch(e){node._hfAnalysis={warnings:[e.message]};htmlFramerRender(node)}};
  fileInput.onchange=()=>choose(fileInput.files?.[0]);
  drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');const f=e.dataTransfer.files?.[0];if(f)choose(f)};
  node.querySelector('[data-hf-analyze]').onclick=()=>choose(node._hfFile||fileInput.files?.[0]);
  node.querySelector('[data-hf-publish]').onclick=async()=>{const file=node._hfFile;if(!file)return;const entry=node.querySelector('[data-hf-entry]')?.value||node._hfAnalysis?.entrypoint||'';try{const r=await htmlFramerRequest('upload',{file,entrypoint:entry});if(r.needsEntrypoint){node._hfAnalysis=r.analysis;htmlFramerRender(node);return}node._hfFile=null;node._hfAnalysis=null;node._hfData=r;htmlFramerRender(node)}catch(e){alert(e.message)}};
  node.querySelector('[data-hf-capture]')?.addEventListener('click',async()=>{const url=node.querySelector('[data-hf-url]')?.value?.trim(),msg=node.querySelector('[data-hf-capture-msg]');if(!url)return;msg.textContent='Capturing static snapshot…';try{const r=await htmlFramerRequest('capture-url',{url});node._hfData=r;msg.textContent=r.message||'Static snapshot imported.';htmlFramerRender(node)}catch(e){msg.textContent=e.message}});
  node.querySelectorAll('[data-hf-height]').forEach(el=>el.oninput=()=>{el.closest('.html-framer-row').querySelector('[data-hf-height-value]').textContent=`${el.value}px`});
  node.querySelectorAll('[data-hf-save]').forEach(btn=>btn.onclick=async()=>{const row=btn.closest('[data-hf-id]');try{node._hfData=await htmlFramerRequest('update',{frameId:row.dataset.hfId,title:row.querySelector('[data-hf-title]').value,enabled:row.querySelector('[data-hf-enabled]').checked,actionReaderEnabled:row.querySelector('[data-hf-track]').checked,height:Number(row.querySelector('[data-hf-height]').value)});htmlFramerRender(node)}catch(e){alert(e.message)}});
  node.querySelectorAll('[data-hf-move]').forEach(btn=>btn.onclick=async()=>{const row=btn.closest('[data-hf-id]');try{node._hfData=await htmlFramerRequest('move',{frameId:row.dataset.hfId,direction:btn.dataset.hfMove});htmlFramerRender(node)}catch(e){alert(e.message)}});
  node.querySelectorAll('[data-hf-delete]').forEach(btn=>btn.onclick=async()=>{const row=btn.closest('[data-hf-id]');if(!confirm('Delete this HTML frame module and its stored ZIP/files?'))return;try{node._hfData=await htmlFramerRequest('delete',{frameId:row.dataset.hfId});htmlFramerRender(node)}catch(e){alert(e.message)}});
}
function bindHtmlFramerManagers(scope){scope.querySelectorAll('[data-html-framer-manager]').forEach(node=>htmlFramerLoad(node))}

function renderProjectPresentation(){const box=$('#projectPresentationCard'),p=state?.project_presentation||{};if(!box)return;box.innerHTML=`<div class="eyebrow">PROJECT CHROME</div><h2>Module title bars + collapse</h2><div class="desc">Set the project-wide behavior here. Every project module can still override these three choices individually in Module Control Center.</div><div class="project-presentation-grid"><div class="field"><label>Collapse capability</label><select id="projectCollapseMode"><option value="inherit" ${p.collapseMode==='inherit'?'selected':''}>Inherit LOOM global (${p.globalDefaults?.collapseEnabled?'enabled':'disabled'})</option><option value="enabled" ${p.collapseMode==='enabled'?'selected':''}>Enabled</option><option value="disabled" ${p.collapseMode==='disabled'?'selected':''}>Completely disabled</option></select></div><div class="field"><label>Module title bars</label><select id="projectTitleBarMode"><option value="inherit" ${p.titleBarMode==='inherit'?'selected':''}>Inherit LOOM global (${p.globalDefaults?.titleBarsEnabled?'shown':'hidden'})</option><option value="show" ${p.titleBarMode==='show'?'selected':''}>Show</option><option value="hide" ${p.titleBarMode==='hide'?'selected':''}>Hide</option></select></div><div class="field"><label>Initial module state</label><select id="projectInitialState"><option value="inherit" ${p.initialState==='inherit'?'selected':''}>Inherit LOOM global (${esc(p.globalDefaults?.initialState||'expanded')})</option><option value="expanded" ${p.initialState==='expanded'?'selected':''}>Expanded</option><option value="collapsed" ${p.initialState==='collapsed'?'selected':''}>Collapsed</option></select></div></div><div class="buttons"><button class="save" id="saveProjectPresentation">Save Project Presentation</button></div><div class="msg">Current effective behavior: title bars ${p.titleBarsEnabled?'shown':'hidden'} · collapse ${p.collapseEnabled?'enabled':'disabled'} · first visit ${esc(p.effectiveInitialState||'expanded')}.</div>`;$('#saveProjectPresentation').onclick=async()=>{try{state=await post({action:'module-presentation-save',project:$('#project').value,presentation:{collapseMode:$('#projectCollapseMode').value,titleBarMode:$('#projectTitleBarMode').value,initialState:$('#projectInitialState').value}});renderProjectPresentation();renderModuleControl();renderModules();decorateProjectStaticCards();toastOk('Project module presentation updated.')}catch(e){toastErr(e.message)}};decorateProjectStaticCards()}
function renderModuleControl(){const list=$('#moduleControlList'),q=($('#moduleControlSearch')?.value||'').trim().toLowerCase(),catalog=state?.module_catalog||[];if(!list)return;const rows=catalog.filter(m=>!q||[m.name,m.actionId,m.source,m.scope].some(v=>String(v||'').toLowerCase().includes(q)));list.innerHTML=rows.length?rows.map(m=>{const mobileSupported=m.mobileVisibilitySupported!==false&&m.scope==='project',c=m.chrome||{};const chrome=m.scope==='project'?`<div class="module-chrome-controls"><label>Collapse<select data-chrome="collapseMode"><option value="inherit" ${c.collapseMode==='inherit'?'selected':''}>Inherit project</option><option value="enabled" ${c.collapseMode==='enabled'?'selected':''}>Enabled</option><option value="disabled" ${c.collapseMode==='disabled'?'selected':''}>Disabled</option></select></label><label>Title bar<select data-chrome="titleBarMode"><option value="inherit" ${c.titleBarMode==='inherit'?'selected':''}>Inherit project</option><option value="show" ${c.titleBarMode==='show'?'selected':''}>Show</option><option value="hide" ${c.titleBarMode==='hide'?'selected':''}>Hide</option></select></label><label>Initial state<select data-chrome="initialState"><option value="inherit" ${c.initialState==='inherit'?'selected':''}>Inherit project</option><option value="expanded" ${c.initialState==='expanded'?'selected':''}>Expanded</option><option value="collapsed" ${c.initialState==='collapsed'?'selected':''}>Collapsed</option></select></label></div>`:'';return `<div class="module-control-row" data-control-module="${esc(m.actionId)}" data-control-scope="${esc(m.scope)}"><label class="module-control-switch" title="${m.enabled?'Disable':'Enable'} ${esc(m.name)}"><input class="module-enabled-toggle" type="checkbox" ${m.enabled?'checked':''} ${m.locked?'disabled':''}><span></span></label><div class="module-control-name"><strong>${esc(m.name)}</strong><small>${esc(m.actionId)} · ${esc(m.description||'')}</small></div><span class="module-control-badge">${esc(m.scope)} · ${esc(m.source)}</span>${mobileSupported?`<label class="module-mobile-control"><input class="module-mobile-toggle" type="checkbox" ${m.hideOnMobile?'checked':''}><span>Hide on mobile</span></label>`:`<span class="module-mobile-control disabled">Desktop + mobile</span>`}<span class="module-control-status">${m.enabled?'Enabled':'Disabled'}</span>${chrome}</div>`}).join(''):'<div class="empty" style="margin:12px">No matching modules.</div>';list.querySelectorAll('[data-control-module] .module-enabled-toggle').forEach(el=>el.onchange=async()=>{const row=el.closest('[data-control-module]'),status=row.querySelector('.module-control-status');status.textContent='Saving…';el.disabled=true;try{const d=await post({action:'module-toggle',project:$('#project').value,moduleId:row.dataset.controlModule,scope:row.dataset.controlScope,enabled:el.checked});if(row.dataset.controlScope==='global'){globalState=d;state=await post({action:'settings',project:$('#project').value})}else state=d;renderProjectPresentation();renderModuleControl();renderModules();if(row.dataset.controlScope==='global')renderGlobalModules();toastOk(`${row.dataset.controlModule} ${el.checked?'enabled':'disabled'}.`,'Module updated')}catch(e){el.checked=!el.checked;el.disabled=false;status.textContent=e.message;toastErr(e.message)}});list.querySelectorAll('[data-control-module] .module-mobile-toggle').forEach(el=>el.onchange=async()=>{const row=el.closest('[data-control-module]'),status=row.querySelector('.module-control-status');status.textContent='Saving…';el.disabled=true;try{state=await post({action:'module-mobile-visibility',project:$('#project').value,moduleId:row.dataset.controlModule,scope:row.dataset.controlScope,hideOnMobile:el.checked});renderModuleControl();renderModules();toastOk(`${row.dataset.controlModule} mobile visibility applied.`,'Module updated')}catch(e){el.checked=!el.checked;el.disabled=false;status.textContent=e.message;toastErr(e.message)}});list.querySelectorAll('[data-control-module] [data-chrome]').forEach(el=>el.onchange=async()=>{const row=el.closest('[data-control-module]'),status=row.querySelector('.module-control-status'),payload={};row.querySelectorAll('[data-chrome]').forEach(x=>payload[x.dataset.chrome]=x.value);status.textContent='Saving…';try{state=await post({action:'module-presentation-override',project:$('#project').value,moduleId:row.dataset.controlModule,presentation:payload});renderProjectPresentation();renderModuleControl();renderModules();toastOk(`${row.dataset.controlModule} title/collapse behavior updated.`,'Module presentation')}catch(e){status.textContent=e.message;toastErr(e.message)}});decorateProjectStaticCards()}

function renderModules(){const box=$('#modules'),mods=state?.modules||[];box.innerHTML=mods.map(m=>{const fields=m.admin_settings?.fields||[];return `<section class="module" data-module="${esc(m.actionId)}" data-admin-config-card="${esc(m.actionId)}" data-admin-title="${esc(m.admin_settings?.title||m.name)}"><div class="eyebrow">${m.source==='core-project'?'CORE PROJECT · ':''}${esc(m.order)} · ${esc(m.actionId)}</div><h2>${esc(m.admin_settings?.title||m.name)}</h2><div class="desc">${esc(m.admin_settings?.description||m.description)}</div>${fields.map(f=>fieldHtml(f,m.values?.[f.id]??m.defaults?.[f.id])).join('')}${(m.admin_settings?.tools||[]).map(t=>toolHtml(t,m)).join('')}${fields.length?`<div class="buttons"><button class="save" data-save data-loom-tip="Apply these module settings to the selected project. A toast confirms the saved state.">Save</button><button class="reset" data-reset data-loom-tip="Remove project overrides for this module and restore its defaults.">Reset defaults</button></div>`:''}<div class="msg" data-msg></div></section>`}).join('');box.querySelectorAll('input[type=range]').forEach(el=>el.oninput=()=>{const f=mods.flatMap(x=>x.admin_settings?.fields||[]).find(x=>x.id===el.dataset.field),out=box.querySelector(`[data-value="${CSS.escape(el.dataset.field)}"]`);if(out)out.textContent=el.value+(f?.unit||'')});bindConditionalFields(box);bindHtmlFramerManagers(box);bindShowcaseManagers(box);bindSocialLinkHelpers(box);box.querySelectorAll('[data-save]').forEach(btn=>btn.onclick=async()=>{const card=btn.closest('.module'),m=mods.find(x=>x.actionId===card.dataset.module),vals={};for(const f of m.admin_settings.fields){const el=card.querySelector(`[data-field="${CSS.escape(f.id)}"]`);vals[f.id]=readAdminField(el,f)}try{state=await post({action:'save',project:$('#project').value,moduleId:card.dataset.module,values:vals});renderModules();toastOk(`${m.admin_settings?.title||m.name} settings applied.`)}catch(e){card.querySelector('[data-msg]').textContent=e.message;toastErr(e.message)}});box.querySelectorAll('[data-reset]').forEach(btn=>btn.onclick=async()=>{const card=btn.closest('.module');try{state=await post({action:'reset',project:$('#project').value,moduleId:card.dataset.module});renderModules();toastOk('Module defaults restored.','Defaults restored')}catch(e){card.querySelector('[data-msg]').textContent=e.message;toastErr(e.message)}});box.querySelectorAll('[data-config-preset]').forEach(btn=>btn.onclick=async()=>{const card=btn.closest('.module');try{state=await post({action:'apply-preset',project:$('#project').value,moduleId:card.dataset.module,presetId:btn.dataset.configPreset});renderModules();toastOk('Module preset applied.','Preset applied')}catch(e){card.querySelector('[data-msg]').textContent=e.message;toastErr(e.message)}});box.querySelectorAll('[data-favicon-upload]').forEach(btn=>btn.onclick=async()=>{const card=btn.closest('.module'),file=card.querySelector('[data-favicon-file]')?.files?.[0];if(!file)return;try{state=await post({action:'favicon-upload',project:$('#project').value,moduleId:card.dataset.module,pngBase64:await imageFileToPngDataUrl(file)});renderModules()}catch(e){card.querySelector('[data-msg]').textContent=e.message}});box.querySelectorAll('[data-favicon-logo]').forEach(btn=>btn.onclick=async()=>{const card=btn.closest('.module');try{state=await post({action:'favicon-use-logo',project:$('#project').value,moduleId:card.dataset.module});renderModules()}catch(e){card.querySelector('[data-msg]').textContent=e.message}});box.querySelectorAll('[data-emoji-toggle]').forEach(btn=>btn.onclick=()=>btn.closest('.orb-admin-row').querySelector('.emoji-pop')?.classList.toggle('open'));box.querySelectorAll('[data-emoji-value]').forEach(btn=>btn.onclick=()=>{const row=btn.closest('.orb-admin-row');row.querySelector('[data-orb-emoji]').value=btn.dataset.emojiValue;row.querySelector('.emoji-pop').classList.remove('open')});box.querySelectorAll('[data-orb-save]').forEach(btn=>btn.onclick=async()=>{const card=btn.closest('.module'),targets={};card.querySelectorAll('[data-orb-target]').forEach(row=>{targets[row.dataset.orbTarget]={captured:!!row.querySelector('[data-orb-captured]').checked,emoji:row.querySelector('[data-orb-emoji]').value.trim()}});try{state=await post({action:'orb-save',project:$('#project').value,moduleId:card.dataset.module,targets});renderModules()}catch(e){card.querySelector('[data-msg]').textContent=e.message}});decorateRenderedCards(box,'project-modules')}
function renderUserList(){const q=$('#userSearch').value.trim().toLowerCase();const rows=usersState.filter(u=>!q||[u.username,u.email,u.subjectId,u.lastIp,u.lastIpDisplay].some(v=>String(v||'').toLowerCase().includes(q)));$('#userList').innerHTML=rows.length?rows.map(u=>`<button class="user-row ${selected&&selected.subjectType===u.subjectType&&selected.subjectId===u.subjectId?'active':''}" data-type="${esc(u.subjectType)}" data-id="${esc(u.subjectId)}"><strong>${esc(u.username||'(unnamed profile)')}</strong><small>${u.registered?'Permanent account':'Guest Identity'} · ${esc(u.email||u.subjectId)}</small><small>${u.banned?'🚫 BANNED · ':''}${esc(u.lastIpDisplay||u.lastIp||'No IP captured')} · ${esc(fmt(u.lastSeen))}</small></button>`).join(''):'<div class="empty">No matching users.</div>';document.querySelectorAll('.user-row').forEach(b=>b.onclick=()=>loadUserDetail(b.dataset.type,b.dataset.id))}
async function loadUsers(){const j=await usersPost({action:'list'});usersState=j.users||[];renderUserList()}
function profileTimes(u){const ps=u.profiles||[];let created=u.account?.createdAt||null,updated=u.account?.updatedAt||null;for(const p of ps){if(p.createdAt&&(!created||String(p.createdAt)<String(created)))created=p.createdAt;if(p.updatedAt&&(!updated||String(p.updatedAt)>String(updated)))updated=p.updatedAt}return {created,updated}}
function renderUserDetail(u){selected={subjectType:u.subjectType,subjectId:u.subjectId};renderUserList();const times=profileTimes(u),account=u.account||{},st=u.projectState||{},activity=u.activity||{},avatar=u.avatarClientId?`../api/profile-avatar.php?action=image&clientId=${encodeURIComponent(u.avatarClientId)}&project=${encodeURIComponent($('#project').value)}&v=${Date.now()}`:'';$('#userDetail').innerHTML=`<div class="detail-head">${avatar?`<img class="avatar" src="${avatar}" onerror="this.style.display='none'">`:''}<div><div class="eyebrow">${esc(u.registered?'PERMANENT ACCOUNT':'GUEST IDENTITY')}</div><h2>${esc(u.currentProjectIdentity?.username||u.subjectId)}</h2><div class="status-row"><span class="pill">${esc(account.privilege||'User')}</span>${st.banned?'<span class="pill bad">Banned from project</span>':'<span class="pill">Allowed in project</span>'}<span class="pill ${u.storageMode==='database'?'':'warn'}">${esc(u.storageMode)}</span></div></div></div><div class="detail-grid"><div class="info"><b>Subject ID</b><code>${esc(u.subjectId)}</code></div><div class="info"><b>Profile Since</b>${esc(fmt(times.created))}</div><div class="info"><b>Last Saved / Seen</b>${esc(fmt(times.updated||activity.lastSeen))}</div><div class="info"><b>Linked Clients</b>${esc((u.clients||[]).length)}</div><div class="info"><b>LOOM Username</b>${esc(u.globalProfile?.username||'—')}</div><div class="info"><b>LOOM Avatar</b>${esc(u.globalProfile?.avatarMode||'loom-default')}</div><div class="info"><b>Project Sessions</b>${esc(activity.sessionCount||0)}</div><div class="info"><b>Project Events</b>${esc(activity.eventCount||0)}</div></div><div class="module" style="margin-top:14px"><div class="eyebrow">LINKED IDENTITY DETAILS</div><h2>Clients & profiles</h2>${(u.clients||[]).length?`<table class="ip-table"><thead><tr><th>Client ID</th><th>Profile ID</th><th>Username</th><th>Created</th><th>Updated</th></tr></thead><tbody>${u.clients.map(cid=>{const p=(u.profiles||[]).find(x=>x.clientId===cid)||{};return `<tr><td><code>${esc(cid)}</code></td><td><code>${esc(p.profileId||'—')}</code></td><td>${esc(p.username||'—')}</td><td>${esc(fmt(p.createdAt))}</td><td>${esc(fmt(p.updatedAt))}</td></tr>`}).join('')}</tbody></table>`:'<div class="empty">No linked clients.</div>'}${activity.latestClientMeta?`<div class="detail-grid"><div class="info"><b>Language</b>${esc(activity.latestClientMeta.language||'—')}</div><div class="info"><b>Timezone</b>${esc(activity.latestClientMeta.timezone||'—')}</div><div class="info"><b>Platform</b>${esc(activity.latestClientMeta.platform||'—')}</div><div class="info"><b>User Agent</b><code>${esc(activity.latestClientMeta.userAgent||'—')}</code></div></div>`:''}</div><div class="module" style="margin-top:14px"><div class="eyebrow">RECENT PROJECT ACTIVITY</div><h2>Sessions & actions</h2><div class="detail-grid"><div class="info"><b>First seen</b>${esc(fmt(activity.firstSeen))}</div><div class="info"><b>Last seen</b>${esc(fmt(activity.lastSeen))}</div><div class="info"><b>User actions</b>${esc(activity.userActionCount||0)}</div><div class="info"><b>Failures</b>${esc(activity.failureCount||0)}</div></div>${activity.recentSessions?.length?`<table class="ip-table"><thead><tr><th>Status</th><th>Session ID</th><th>Client</th><th>First</th><th>Last</th><th>Events</th></tr></thead><tbody>${activity.recentSessions.map(x=>`<tr><td>${esc(x.status)}</td><td><code>${esc(x.sessionId)}</code></td><td><code>${esc(x.clientId||'—')}</code></td><td>${esc(fmt(x.firstSeen))}</td><td>${esc(fmt(x.lastSeen))}</td><td>${esc(x.eventCount||0)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No session history in this project yet.</div>'}${activity.topActions?.length?`<div class="setup"><b>Top recorded actions</b><br>${activity.topActions.map(x=>`<code>${esc(x.actionId)}</code> × ${esc(x.count)}`).join(' &nbsp; · &nbsp; ')}</div>`:''}</div><div class="module" style="margin-top:14px"><div class="eyebrow">PROJECT IDENTITY · ${esc($('#project').value)}</div><h2>${esc(u.currentProjectIdentity?.effectiveUsername||u.currentProjectIdentity?.username||u.globalProfile?.username||'Project identity')}</h2><p>This project may inherit the LOOM-wide username/profile picture or override them.</p><div class="field"><label>LOOM-wide username</label><input id="editGlobalUsername" value="${esc(u.globalProfile?.username||'')}"></div><div class="buttons"><button class="save" id="saveGlobalUsername">Change LOOM Username</button></div><div class="field"><label>Project username override</label><input id="editUsername" value="${esc(u.currentProjectIdentity?.username||'')}"></div><div class="buttons"><button class="save" id="saveUsername">Use / Change Project Username</button><button class="secondary" id="useGlobalUsername">Use LOOM Username</button></div><div class="msg" id="userMsg"></div></div><div class="module" style="margin-top:14px"><div class="eyebrow">ALL PROJECT IDENTITIES</div><h2>${esc((u.projectIdentities||[]).length)} identities</h2>${u.projectIdentities?.length?`<table class="ip-table"><thead><tr><th>Project</th><th>Effective username</th><th>Username source</th><th>Avatar mode</th><th>Created</th><th>Updated</th></tr></thead><tbody>${u.projectIdentities.map(x=>`<tr><td>${esc(x.projectName||x.project)}</td><td><b>${esc(x.effectiveUsername||x.username||u.globalProfile?.username||'Not set')}</b></td><td>${esc(x.usernameMode==='global'?'LOOM profile':'Project override')}</td><td>${esc(x.avatarMode||'auto')}</td><td>${esc(fmt(x.createdAt))}</td><td>${esc(fmt(x.updatedAt))}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No project identities yet.</div>'}</div><div class="module" style="margin-top:14px"><div class="eyebrow">PERMANENT ACCOUNT CREDENTIALS</div><p>Email/password belong to the global LOOM account and unlock all of its project identities.</p>${u.registered?`<div class="field"><label>Email</label><input id="editEmail" type="email" value="${esc(account.email||'')}"></div><div class="buttons"><button class="save" id="saveEmail">Change Account Email</button></div><div class="field"><label>New password <span>current password is never shown</span></label><input id="editPassword" type="password" placeholder="8+ characters"></div><div class="buttons"><button class="danger" id="savePassword">Replace Account Password</button></div>`:'<div class="empty">This Guest Identity has no permanent account yet.</div>'}</div><div class="module" style="margin-top:14px"><div class="eyebrow">NETWORK METADATA</div><h2>Known IP addresses</h2><p>Captured by the server and visible to this user in their own Identity Details. Never used as authentication proof.</p>${u.ipHistory?.length?`<table class="ip-table"><thead><tr><th>IP</th><th>First seen</th><th>Last seen</th><th>Seen</th><th>Source</th></tr></thead><tbody>${u.ipHistory.map(x=>`<tr><td><code>${esc(x.ip||'—')}</code>${x.ipVersion?` <span class="pill">${esc(x.ipVersion)}</span>`:''}</td><td>${esc(fmt(x.firstSeen))}</td><td>${esc(fmt(x.lastSeen))}</td><td>${esc(x.seenCount)}</td><td>${esc(x.source||'—')}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No IP captured yet.</div>'}</div><div class="moderation"><div class="eyebrow">PROJECT MODERATION · ${esc($('#project').value)}</div><h2>${st.banned?'Banned profile':'Profile allowed'}</h2><p>${st.banned?'The account still exists, but this identity cannot load or write to this project.':'This identity can access the project normally.'}</p><div class="buttons"><button class="${st.banned?'secondary':'danger'}" id="toggleBan">${st.banned?'Unban Profile':'Ban Profile'}</button></div>${st.banned?`<label class="switchline"><input id="includeData" type="checkbox" ${st.includeData?'checked':''}> Include this banned profile's retained data in project views</label><p style="margin-top:7px">Off by default. Turning it on does not restore access—it only makes retained historical data visible to project/admin views again.</p>`:''}</div>`;
  const msg=()=>$('#userMsg');$('#saveGlobalUsername').onclick=()=>mutateUser('update-global-username',{username:$('#editGlobalUsername').value},'Change this user’s LOOM-wide username?');$('#saveUsername').onclick=()=>mutateUser('update-username',{username:$('#editUsername').value},'Change this project username?');$('#useGlobalUsername').onclick=()=>mutateUser('use-global-username',{},'Make this project inherit the LOOM-wide username?');if(u.registered){$('#saveEmail').onclick=()=>mutateUser('update-email',{email:$('#editEmail').value},'Change this account email?');$('#savePassword').onclick=()=>mutateUser('set-password',{password:$('#editPassword').value},'Replace this user password and revoke their prior login sessions?')}$('#toggleBan').onclick=()=>mutateUser('set-ban',{banned:!st.banned},st.banned?'Unban this profile?':'Ban this profile from this project?');$('#includeData')?.addEventListener('change',async e=>{const ok=confirmPhrase(`${e.target.checked?'Include':'Hide'} this banned profile's retained data in project views?`);if(!ok){e.target.checked=!e.target.checked;return}try{const j=await usersPost({action:'set-include-data',subjectType:u.subjectType,subjectId:u.subjectId,includeData:e.target.checked,confirmPhrase:ok});renderUserDetail(j.user);await loadUsers()}catch(err){alert(err.message);e.target.checked=!e.target.checked}})
}
async function mutateUser(action,payload,message){const ok=confirmPhrase(message);if(!ok)return;try{const j=await usersPost({action,subjectType:selected.subjectType,subjectId:selected.subjectId,confirmPhrase:ok,...payload});renderUserDetail(j.user);await loadUsers()}catch(e){const m=$('#userMsg');if(m)m.textContent=e.message;else alert(e.message)}}
async function loadUserDetail(type,id){try{const j=await usersPost({action:'detail',subjectType:type,subjectId:id});renderUserDetail(j.user)}catch(e){$('#userDetail').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function identityGuestLabel(g){return `${g.status==='attached'?'Attached':'Guest'} · ${String(g.guestId||'').slice(0,18)}…`}
function renderIdentityList(){const q=($('#identitySearch')?.value||'').toLowerCase(),box=$('#identityList');if(!box)return;const rows=(identityState.guests||[]).filter(g=>!q||JSON.stringify(g).toLowerCase().includes(q));box.innerHTML=rows.map(g=>`<button class="user-row ${selectedGuestId===g.guestId?'active':''}" data-guest-id="${esc(g.guestId)}"><strong>${esc(identityGuestLabel(g))}</strong><small>${esc(g.status)} · ${esc(g.clientCount)} device/client${g.clientCount===1?'':'s'}${g.attachedUserId?` · → ${esc(g.attachedUserId)}`:''}</small><small>Seen ${esc(fmt(g.updatedAt))}</small></button>`).join('')||'<div class="empty">No Guest Identities match.</div>';box.querySelectorAll('[data-guest-id]').forEach(b=>b.onclick=()=>loadIdentityDetail(b.dataset.guestId))}
async function loadIdentities(){try{identityState=await identitiesPost({action:'list'});renderIdentityList()}catch(e){$('#identityList').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function renderIdentityDetail(d,users){const g=d.guest||{},a=d.activity||{},box=$('#identityDetail');selectedGuestId=g.guestId;renderIdentityList();const userOpts=(users||[]).map(u=>`<option value="${esc(u.userId)}">${esc(u.globalProfile?.username||u.email||u.userId)} · ${esc(u.email||u.userId)}</option>`).join('');box.innerHTML=`<div class="detail-head"><div><div class="eyebrow">GUEST IDENTITY</div><h2>${esc(g.guestId||'')}</h2><p>Status: <b>${esc(g.status||'')}</b>${g.attachedUserId?` · attached to <code>${esc(g.attachedUserId)}</code>`:''}${d.canonicalGuest?` · canonical target <code>${esc(d.canonicalGuest.guestId)}</code>`:''}</p></div></div><div class="detail-grid"><div class="info"><b>First seen</b><strong>${esc(fmt(g.createdAt))}</strong></div><div class="info"><b>Last seen</b><strong>${esc(fmt(g.updatedAt))}</strong></div><div class="info"><b>Clients / devices</b><strong>${esc(g.clientCount||0)}</strong></div><div class="info"><b>Snapshots</b><strong>${esc(g.snapshotCount||0)}</strong></div><div class="info"><b>Events</b><strong>${esc(a.eventCount||0)}</strong></div><div class="info"><b>Projects</b><strong>${esc(Object.keys(a.projects||{}).length)}</strong></div></div><div class="module" style="margin-top:14px"><div class="eyebrow">PROVENANCE</div><h2>Preserved activity</h2><p>Guest source history is retained even after attachment. Account attachment changes active ownership/access; it does not erase the Guest Identity.</p>${Object.keys(d.clients||{}).length?`<table class="ip-table"><thead><tr><th>Client</th><th>First seen</th><th>Last seen</th></tr></thead><tbody>${Object.entries(d.clients).map(([id,m])=>`<tr><td><code>${esc(id)}</code></td><td>${esc(fmt(m.firstSeen))}</td><td>${esc(fmt(m.lastSeen))}</td></tr>`).join('')}</tbody></table>`:''}</div><div class="module" style="margin-top:14px"><div class="eyebrow">SUPPORT RECOVERY</div><h2>Recovery tools</h2><p>Network, project, action-pattern, username, and timing signals can help find candidates, but are never proof of ownership and never trigger automatic merging.</p><div class="buttons"><button class="secondary" id="adminRecoveryCode" ${g.status!=='unattached'?'disabled':''}>Issue Recovery Code</button></div><div id="adminRecoveryOut" class="msg"></div></div><div class="module" style="margin-top:14px"><div class="eyebrow">ATTACH / CONVERT</div><h2>Permanent ownership</h2>${g.status==='attached'?`<div class="empty">Already attached to <code>${esc(g.attachedUserId||'')}</code>.</div>`:g.status==='merged'?`<div class="empty">This source Guest Identity is preserved as merge provenance. Perform ownership operations on canonical target <code>${esc(d.canonicalGuest?.guestId||g.mergedIntoGuestId||'')}</code>.</div>`:`<div class="field"><label>Attach to existing account</label><select id="attachUserId"><option value="">Choose permanent account…</option>${userOpts}</select></div><div class="buttons"><button class="save" id="attachGuest">Attach Guest History</button><button class="secondary" id="convertGuest">Create New Account from Guest</button></div><div class="field"><label>Merge into another unattached Guest Identity</label><select id="mergeTargetGuest"><option value="">Choose target Guest Identity…</option>${(identityState.guests||[]).filter(x=>x.guestId!==g.guestId&&x.status==='unattached').map(x=>`<option value="${esc(x.guestId)}">${esc(x.guestId)} · ${esc(fmt(x.updatedAt))}</option>`).join('')}</select></div><div class="buttons"><button class="secondary" id="mergeGuest">Merge Guest → Guest</button></div>`}<div id="identityMsg" class="msg"></div></div><div class="module" style="margin-top:14px"><div class="eyebrow">POSSIBLE RELATED GUESTS</div><h2>Manual evidence review</h2><p>These are search candidates only. LOOM never auto-attaches based on fuzzy evidence.</p><div class="identity-evidence">${(d.relatedGuests||[]).map(c=>`<div class="identity-evidence-row"><b>${esc(c.guest.guestId)}</b> · evidence score ${esc(c.evidenceScore)}<br>${c.signals.map(s=>`<span class="${s.weight==='strong'?'identity-strong':'identity-low'}">${esc(s.kind)} (${esc(s.weight)}): ${esc(s.detail)}</span>`).join('<br>')}</div>`).join('')||'<div class="empty">No related Guest Identity candidates found.</div>'}</div></div><div class="module" style="margin-top:14px"><div class="eyebrow">MERGE CONFLICTS</div><h2>${esc((d.conflicts||[]).length)} preserved conflict records</h2>${d.conflicts?.length?`<table class="ip-table"><thead><tr><th>Project / module</th><th>Path</th><th>Resolution</th></tr></thead><tbody>${d.conflicts.slice(0,30).map(c=>`<tr><td>${esc(c.project||'')}<br><code>${esc(c.module||'')}</code></td><td><code>${esc(c.path||'(root)')}</code></td><td>${esc(c.resolution||'')}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No merge conflicts recorded.</div>'}</div>`;
  $('#adminRecoveryCode')?.addEventListener('click',async()=>{const ok=confirmPhrase('Issue or rotate a recovery code for this Guest Identity?');if(!ok)return;try{const r=await identitiesPost({action:'issue-recovery',guestId:g.guestId,confirmPhrase:ok});$('#adminRecoveryOut').innerHTML=`<div class="identity-code">${esc(r.recoveryCode)}</div><div class="msg">Give this code only after support has verified the recovery request. LOOM stores only its hash.</div>`}catch(e){$('#adminRecoveryOut').textContent=e.message}});
  $('#attachGuest')?.addEventListener('click',async()=>{const uid=$('#attachUserId').value;if(!uid){$('#identityMsg').textContent='Choose a permanent account.';return}const ok=confirmPhrase(`Attach this Guest History to ${uid}? Source history will be preserved.`);if(!ok)return;try{const r=await identitiesPost({action:'attach',guestId:g.guestId,userId:uid,confirmPhrase:ok});renderIdentityDetail(r.detail,identityState.users);await loadIdentities()}catch(e){$('#identityMsg').textContent=e.message}});
  $('#convertGuest')?.addEventListener('click',async()=>{const email=prompt('Email for the new permanent account:','');if(!email)return;const password=prompt('Temporary password (8+ characters). The user can replace it after signing in:','');if(!password)return;const ok=confirmPhrase(`Create a permanent LOOM account for ${email} and attach this Guest History?`);if(!ok)return;try{const r=await identitiesPost({action:'convert',guestId:g.guestId,email,password,confirmPhrase:ok});renderIdentityDetail(r.detail,identityState.users);await loadIdentities()}catch(e){$('#identityMsg').textContent=e.message}});
  $('#mergeGuest')?.addEventListener('click',async()=>{const target=$('#mergeTargetGuest').value;if(!target){$('#identityMsg').textContent='Choose a target Guest Identity.';return}const ok=confirmPhrase(`Merge ${g.guestId} into ${target}? Both source histories remain preserved.`);if(!ok)return;try{const r=await identitiesPost({action:'merge-guests',sourceGuestId:g.guestId,targetGuestId:target,confirmPhrase:ok});selectedGuestId=target;renderIdentityDetail(r.detail,identityState.users);await loadIdentities()}catch(e){$('#identityMsg').textContent=e.message}})
}
async function loadIdentityDetail(guestId){try{const r=await identitiesPost({action:'detail',guestId});identityState.users=r.users||identityState.users;renderIdentityDetail(r.detail,identityState.users)}catch(e){$('#identityDetail').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function renderAccess(){
  const a=accessState?.access||accessState||{},cur=a.current||{},owner=a.systemOwner||{};
  $('#accessSummary').innerHTML=`<span class="pill">Your role: ${esc(cur.role||'member')}</span>${owner.isCurrent?'<span class="pill">System Owner</span>':''}<span class="pill">${esc((cur.capabilities||[]).length)} capabilities</span>`;
  const subjects=a.subjects||[],users=subjects.filter(x=>x.type==='user');
  $('#loomAdminSubject').innerHTML='<option value="">Choose permanent account…</option>'+users.map(x=>`<option value="${esc(x.id)}">${esc(x.label)}${x.secondary?` · ${esc(x.secondary)}`:''}</option>`).join('');
  $('#projectAccessSubject').innerHTML='<option value="">Choose account or guest…</option>'+subjects.map(x=>`<option value="${esc(x.type+':'+x.id)}">${x.type==='guest'?'Guest · ':'Account · '}${esc(x.label)}${x.secondary?` · ${esc(x.secondary)}`:''}</option>`).join('');
  $('#loomAdminAccessCard')?.classList.toggle('hidden',!a.canViewLoomAdmins);
  $('#grantLoomAdmin').disabled=!a.canManageLoomAdmins;
  $('#loomAdminList').innerHTML=(a.loomAdmins||[]).length?(a.loomAdmins||[]).map(x=>`<div style="display:flex;justify-content:space-between;gap:8px;align-items:center;padding:7px 0;border-bottom:1px solid #e8eee9"><span><b>${esc(x.label||x.userId)}</b><br><small>${esc(x.email||x.userId)}</small></span>${a.canManageLoomAdmins?`<button class="danger" data-revoke-loom="${esc(x.userId)}">Revoke</button>`:''}</div>`).join(''):'No secondary LOOM Admins.';
  $('#projectAccessList').innerHTML=(a.projectGrants||[]).length?(a.projectGrants||[]).map(x=>`<div style="display:flex;justify-content:space-between;gap:8px;align-items:center;padding:7px 0;border-bottom:1px solid #e8eee9"><span><b>${esc(x.label)}</b> · ${esc(x.role)}<br><small>${esc(x.type)} · ${esc(x.id)}</small></span><button class="danger" data-revoke-project-type="${esc(x.type)}" data-revoke-project-id="${esc(x.id)}">Revoke</button></div>`).join(''):'No delegated project access.';
  document.querySelectorAll('[data-revoke-loom]').forEach(b=>b.onclick=async()=>{if(!confirm('Revoke this secondary LOOM Admin?'))return;try{accessState=await accessPost({action:'revoke-loom-admin',userId:b.dataset.revokeLoom});renderAccess()}catch(e){$('#accessMsg').textContent=e.message}});
  document.querySelectorAll('[data-revoke-project-id]').forEach(b=>b.onclick=async()=>{if(!confirm('Revoke this project access grant?'))return;try{accessState=await accessPost({action:'revoke-project',subjectType:b.dataset.revokeProjectType,subjectId:b.dataset.revokeProjectId});renderAccess()}catch(e){$('#accessMsg').textContent=e.message}});
}
async function loadAccess(){try{accessState=await accessPost({action:'status'});renderAccess()}catch(e){$('#accessMsg').textContent=e.message}}
function renderDb(){const d=dbState?.database||{};$('#dbHost').value=d.host||'';$('#dbPort').value=d.port||3306;$('#dbName').value=d.database||'';$('#dbUser').value=d.username||'';$('#dbPass').value='';$('#dbStatus').innerHTML=`<span class="pill ${d.connected?'':'warn'}">${d.connected?'Connected':'Not connected'}</span><span class="pill ${d.initialized?'':'warn'}">${d.initialized?'Schema initialized':'Schema not initialized'}</span>`;$('#storagePill').textContent=d.initialized?'Storage: SQL permanent':'Storage: durable local'}
function renderIntegrity(i){if(!i){$('#integritySummary').innerHTML='';$('#integrityIssues').textContent='Run a scan to inspect the database.';return}const sum=i.summary||{},issues=i.issues||[];$('#integritySummary').innerHTML=`<span class="pill ${i.healthy?'':'bad'}">${i.healthy?'Healthy':'Needs attention'}</span><span class="pill ${sum.critical?'bad':''}">${sum.critical||0} critical</span><span class="pill ${sum.warnings?'warn':''}">${sum.warnings||0} warnings</span>`;$('#integrityIssues').innerHTML=issues.length?issues.map(x=>`<div style="padding:8px 0;border-bottom:1px solid #e5ece6"><b>${esc(x.severity.toUpperCase())} · ${esc(x.code)}</b><br>${esc(x.message)}${x.repairable?' <span class="pill">safe repair</span>':''}</div>`).join(''):'<b>No integrity problems detected.</b><br>The core LOOM SQL relationships checked by this release are consistent.'}
async function scanIntegrity(){try{const r=await dbPost({action:'integrity-scan'});renderIntegrity(r.integrity);$('#integrityMsg').textContent='Integrity scan complete.';return r.integrity}catch(e){$('#integrityMsg').textContent=e.message;throw e}}
async function loadDb(){try{dbState=await dbPost({action:'status'});renderDb()}catch(e){$('#dbMsg').textContent=e.message}}
async function loadProjects(){const r=await fetch(`../api/projects.php?clientId=${encodeURIComponent(identity.clientId)}&_=${Date.now()}`,{cache:'no-store'}),j=await r.json(),sel=$('#project'),requested=new URLSearchParams(location.search).get('project');projectsState=j.projects||[];if(currentStatus&&!currentStatus.isAdmin&&requested)projectsState=projectsState.filter(p=>p.slug===requested);sel.innerHTML=projectsState.map(p=>`<option value="${esc(p.slug)}">${esc(p.name)}</option>`).join('');if(!sel.value)throw new Error('No delegated project is available for this account.');if(requested&&[...sel.options].some(o=>o.value===requested))sel.value=requested;sel.onchange=async()=>{await loadSettings();if(tab==='users'){selected=null;await loadUsers();$('#userDetail').innerHTML='<div class="empty">Select a user or client profile.</div>'}}}
async function loadSettings(){const project=$('#project').value;state=await post({action:'settings',project});const info=(projectsState||[]).find(x=>x.slug===project);$('#appLink').href=info?.app_url||`../projects/${encodeURIComponent(project)}/app/?project=${encodeURIComponent(project)}`;if($('#pegLink'))$('#pegLink').href=`../pegboard/?project=${encodeURIComponent(project)}`;if($('#regLink'))$('#regLink').href=`../registry/?project=${encodeURIComponent(project)}`;renderProjectProfile();renderProjectPresentation();renderModuleControl();renderModules();decorateProjectStaticCards()}
function showTab(next){tab=next;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));$('#loomSettingsPanel').classList.toggle('active',tab==='loom');$('#projectSettingsPanel').classList.toggle('active',tab==='project');$('#usersPanel').classList.toggle('active',tab==='users');$('#identitiesPanel').classList.toggle('active',tab==='identities');$('#accessPanel').classList.toggle('active',tab==='access');$('#databasePanel').classList.toggle('active',tab==='database');$('#projectChooser').classList.toggle('hidden',!(tab==='project'||tab==='users'||tab==='access'));if(tab==='loom')loadGlobalSettings();if(tab==='project')loadSettings();if(tab==='users')loadUsers();if(tab==='identities')loadIdentities();if(tab==='access')loadAccess();if(tab==='database')loadDb()}
$('#grantLoomAdmin')?.addEventListener('click',async()=>{const userId=$('#loomAdminSubject').value;if(!userId)return;try{accessState=await accessPost({action:'grant-loom-admin',userId});renderAccess();toastOk('Secondary LOOM Admin granted.','Access updated')}catch(e){$('#accessMsg').textContent=e.message;toastErr(e.message)}});
$('#grantProjectAccess')?.addEventListener('click',async()=>{const raw=$('#projectAccessSubject').value;if(!raw)return;const [subjectType,...rest]=raw.split(':'),subjectId=rest.join(':');try{accessState=await accessPost({action:'grant-project',subjectType,subjectId,role:$('#projectAccessRole').value});renderAccess();toastOk('Project access delegated.','Access updated')}catch(e){$('#accessMsg').textContent=e.message;toastErr(e.message)}});
$('#moduleControlSearch')?.addEventListener('input',renderModuleControl);document.querySelectorAll('.tab').forEach(x=>x.onclick=()=>showTab(x.dataset.tab));$('#userSearch').oninput=renderUserList;$('#userRefresh').onclick=loadUsers;$('#identitySearch').oninput=renderIdentityList;$('#identityRefresh').onclick=loadIdentities;$('#dbSave').onclick=async()=>{try{dbState=await dbPost({action:'configure',config:{host:$('#dbHost').value,port:Number($('#dbPort').value||3306),database:$('#dbName').value,username:$('#dbUser').value,password:$('#dbPass').value}});$('#dbMsg').textContent=dbState.message;renderDb()}catch(e){$('#dbMsg').textContent=e.message}};$('#dbInit').onclick=async()=>{try{dbState=await dbPost({action:'initialize'});$('#dbMsg').textContent=dbState.message;renderDb()}catch(e){$('#dbMsg').textContent=e.message}};$('#dbMigrate').onclick=async()=>{try{dbState=await dbPost({action:'migrate'});$('#dbMsg').textContent=`${dbState.message} ${JSON.stringify(dbState.migrated)}`;renderDb()}catch(e){$('#dbMsg').textContent=e.message}};$('#integrityScan').onclick=scanIntegrity;$('#integrityBackup').onclick=async()=>{try{const r=await dbPost({action:'integrity-backup'});$('#integrityMsg').textContent=`Snapshot ${r.backup.backupId} created on the protected server storage.`}catch(e){$('#integrityMsg').textContent=e.message}};$('#integrityRepair').onclick=async()=>{const confirmText=prompt('Safe Repair will create a database snapshot first and reconcile known identity mappings. Type CONFIRM to continue.','');if(confirmText!=='CONFIRM')return;try{const r=await dbPost({action:'integrity-repair',confirm:'CONFIRM'});$('#integrityMsg').textContent=`Repair complete. Backup: ${r.repair.backup.backupId}. Actions: ${(r.repair.actions||[]).join(', ')||'none needed'}`;renderIntegrity(r.repair.scan)}catch(e){$('#integrityMsg').textContent=e.message}};
(async()=>{try{const qs=new URLSearchParams(location.search),requestedProject=qs.get('project')||'green-beans';currentStatus=await post({action:'status',claim:false,project:requestedProject});LoomIdentity.setPrivilege(identity.clientId,currentStatus.privilege);$('#who').textContent=`${identity.userLabel} · ${identity.clientId.slice(0,20)}… · ${currentStatus.projectRole||currentStatus.privilege}`;await loadProjects();const caps=currentStatus.capabilities||[],globalAdmin=!!currentStatus.isAdmin;document.querySelector('[data-tab="loom"]')?.classList.toggle('hidden',!globalAdmin);document.querySelector('[data-tab="identities"]')?.classList.toggle('hidden',!globalAdmin);document.querySelector('[data-tab="database"]')?.classList.toggle('hidden',!globalAdmin);document.querySelector('[data-tab="users"]')?.classList.toggle('hidden',!globalAdmin&&!caps.includes('project.users'));document.querySelector('[data-tab="access"]')?.classList.toggle('hidden',!globalAdmin&&!caps.includes('project.access'));if(globalAdmin){await Promise.allSettled([loadGlobalSettings(),loadDb()])}const requestedTab=qs.get('tab'),allowed=[...document.querySelectorAll('.tab:not(.hidden)')].map(x=>x.dataset.tab);const first=allowed.includes(requestedTab)?requestedTab:(globalAdmin?'loom':'project');showTab(first)}catch(e){document.body.innerHTML=`<div style="padding:40px;font-family:system-ui"><h1>Admin access failed</h1><p>${esc(e.message)}</p><a href="../home/">Return home</a></div>`}})();
</script><div id="loomShellFooter"></div><script src="../engine/loom-brand.js?v=0.15.19"></script><script src="../engine/identity.js?v=0.15.19"></script><script src="../engine/loom-global-profile.js?v=0.15.19"></script><script src="../engine/loom-toast.js?v=0.15.19"></script><script src="../engine/loom-shell.js?v=0.15.19"></script><script>(async()=>{if(!window.LoomShell)return;const ident=LoomIdentity.get('loom-admin');await LoomShell.mount({apiBase:'../api',identity:ident,project:new URLSearchParams(location.search).get('project')||'',pageTitle:"Admin",links:[{label:'LOOM Home',href:"../home/"}]})})();</script></body></html>